import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Peregrine — Expo AI Console","description":"A native-feeling AI chat console for iOS and Android — bring your own OpenAI-compatible endpoint, streaming SSE, Keychain-stored keys and a documented design-law compliance matrix.","frontmatter":{"title":"Peregrine — Expo AI Console","description":"A native-feeling AI chat console for iOS and Android — bring your own OpenAI-compatible endpoint, streaming SSE, Keychain-stored keys and a documented design-law compliance matrix."},"headers":[],"relativePath":"en/projects/peregrine/index.md","filePath":"en/projects/peregrine/index.md"}`),a={name:`en/projects/peregrine/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="peregrine-—-expo-ai-console" tabindex="-1">Peregrine — Expo AI Console <a class="header-anchor" href="#peregrine-—-expo-ai-console" aria-label="Permalink to “Peregrine — Expo AI Console”">​</a></h1><p><strong><a href="https://github.com/Godde3s/peregrine" target="_blank" rel="noreferrer">Peregrine</a></strong> is the mobile chapter of my AI infrastructure story: a <strong>native-feeling chat console</strong> that talks to any OpenAI-compatible <code>/v1</code> endpoint — Ollama on your own machine, a self-hosted <a href="/Usf/en/projects/omnirouter/">OmniRouter</a> gateway, or the cloud. There is no Peregrine server: the API key lives in the Keychain, conversations live in MMKV on device.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><ul><li>⚡ <strong>Streaming chat</strong> — SSE deltas parsed with a hand-rolled async generator over plain <code>fetch</code>, abortable mid-flight, non-streaming fallback.</li><li>🔌 <strong>Bring your own endpoint</strong> — any <code>/v1</code>-speaking API; onboarding validates the endpoint with a live connection test.</li><li>🧠 <strong>Model browser</strong> — <code>/v1/models</code> via TanStack Query: shape-matched skeletons, inline errors, pull-to-refresh, native search bar.</li><li>🔐 <strong>Zero-account security</strong> — key in the Keychain (<code>expo-secure-store</code>), transcripts in MMKV, no analytics, no telemetry.</li><li>🎨 <strong>Native by default</strong> — SF Symbols on iOS / Material on Android, system Switch &amp; Slider, large-title collapse, haptics as punctuation, light + dark from day one.</li></ul><h2 id="the-stack" tabindex="-1">The stack <a class="header-anchor" href="#the-stack" aria-label="Permalink to “The stack”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Expo SDK 57 · React Native 0.86 · expo-router · TypeScript strict</span></span>
<span class="line"><span>Reanimated 4 (UI-thread motion) · FlashList · TanStack Query</span></span>
<span class="line"><span>Zustand (two narrow stores) · MMKV · react-native-keyboard-controller</span></span></code></pre></div><p><strong>State is deliberately boring:</strong> server state in TanStack Query, client state in two narrow Zustand stores persisted to MMKV, ephemeral UI state local to components. The composer is an <strong>uncontrolled input</strong> — keystrokes never re-render the conversation list.</p><h2 id="built-to-a-design-bar-not-to-taste" tabindex="-1">Built to a design bar, not to taste <a class="header-anchor" href="#built-to-a-design-bar-not-to-taste" aria-label="Permalink to “Built to a design bar, not to taste”">​</a></h2><p>The screens are built against the <a href="https://github.com/Appllama/appllama-skills" target="_blank" rel="noreferrer">appllama app-design skill</a>: navigation semantics (push vs replace, modal vs sheet, one-way doors guarded with <code>Stack.Protected</code>), anti-slop discipline (one accent, one grey family, a stated radius scale) and a motion budget that lives entirely on the UI thread. The repo ships a <strong>law-by-law compliance matrix</strong> in <a href="https://github.com/Godde3s/peregrine/blob/main/docs/DESIGN.md" target="_blank" rel="noreferrer">docs/DESIGN.md</a> — review becomes mechanical instead of vibes-based.</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prebuild</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # dev build — MMKV needs native code</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run:ios</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">      # or: npx expo run:android</span></span></code></pre></div><p>MIT licensed.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};